import { expect, test, uniqueName } from "../../fixtures";

const W9 = "Legal Name: Acme Freight LLC\nTax ID: 12-3456789\nBusiness Type: LLC\n";
const CONTRACT = "Counterparty: Acme Freight LLC\nEffective Date: 2026-01-01\nExpiry Date: 2027-12-31\n";

// The app compares expiry dates against the server's UTC date, so compute the day in UTC.
function isoDateInDays(days: number): string {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + days);
  return d.toISOString().slice(0, 10);
}

function insuranceText(expiry: string): string {
  return `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${expiry}\n`;
}

test.describe("insurance expiry flag", () => {
  const rows = [
    { days: 0, include: true },
    { days: 30, include: true },
    { days: 31, include: false },
  ];

  for (const { days, include } of rows) {
    test(
      `insurance expiring in ${days} days ${include ? "is" : "is not"} flagged`,
      { tag: "@REV-08" },
      async ({ apiAs }) => {
        // Arrange
        const member = await apiAs("member");
        const created = await member.post("/api/vendors", {
          data: {
            name: uniqueName("Expiry Check"),
            category: "logistics",
            contact_email: "ops@expiry-check.example",
          },
        });
        expect(created.status(), await created.text()).toBe(201);
        const vendor = (await created.json()) as { id: string };

        const uploads: Array<[string, string]> = [
          ["w9", W9],
          ["insurance_certificate", insuranceText(isoDateInDays(days))],
          ["contract", CONTRACT],
        ];
        for (const [kind, text] of uploads) {
          const upload = await member.post(`/api/vendors/${vendor.id}/documents`, {
            multipart: {
              kind,
              file: { name: `${kind}.txt`, mimeType: "text/plain", buffer: Buffer.from(text) },
            },
          });
          expect(upload.status(), await upload.text()).toBe(201);
        }

        // Wait until the insurance certificate has been extracted so the expiry is known.
        await expect
          .poll(
            async () => {
              const res = await member.get(`/api/vendors/${vendor.id}/documents`);
              const docs = (await res.json()) as Array<{ kind: string; status: string }>;
              return docs.find((d) => d.kind === "insurance_certificate")?.status;
            },
            { timeout: 30_000 },
          )
          .toBe("extracted");

        // Act
        const response = await member.get(`/api/vendors/${vendor.id}`);

        // Assert
        expect(response.status(), await response.text()).toBe(200);
        const body = (await response.json()) as { flags: string[] };
        if (include) {
          expect(body.flags, await response.text()).toContain("insurance_expiring_soon");
        } else {
          expect(body.flags, await response.text()).not.toContain("insurance_expiring_soon");
        }
      },
    );
  }
});
